import type { NavBuilding, NavEdge, NavFloor, NavGraph, NavNode } from '../../src/shared/types';
import {
  type NavGraphContractValidationError,
  validateNavGraphPayload,
} from './navGraphSchema';

export interface NormalizedFloorRecord {
  buildingId: number;
  buildingName: string;
  floor: NavFloor;
}

export interface NormalizedNodeRecord {
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
  node: NavNode;
}

export interface NormalizedEdgeRecord {
  buildingId: number;
  floorId: number;
  edge: NavEdge;
  effectiveAccessibleWeight: number;
}

export interface NormalizedNavGraph {
  graph: NavGraph;
  buildingById: Map<number, NavBuilding>;
  floorById: Map<number, NormalizedFloorRecord>;
  floorByBuildingAndNumber: Map<string, NormalizedFloorRecord>;
  nodeById: Map<string, NormalizedNodeRecord>;
  edgeById: Map<string, NormalizedEdgeRecord>;
  outgoingEdgesByNodeId: Map<string, NormalizedEdgeRecord[]>;
}

export type NavGraphNormalizationErrorCode =
  | 'duplicate-building-id'
  | 'duplicate-floor-id'
  | 'duplicate-floor-number-per-building'
  | 'duplicate-node-id'
  | 'duplicate-edge-id'
  | 'node-floor-mismatch'
  | 'edge-node-missing';

export interface NavGraphNormalizationError {
  reason: 'normalization-failure';
  code: NavGraphNormalizationErrorCode;
  message: string;
}

export type NavGraphNormalizationResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphNormalizationError };

export type NavGraphParseAndNormalizeResult =
  | { ok: true; data: NormalizedNavGraph }
  | { ok: false; error: NavGraphContractValidationError | NavGraphNormalizationError };

function fail(
  code: NavGraphNormalizationErrorCode,
  message: string,
): { ok: false; error: NavGraphNormalizationError } {
  return {
    ok: false,
    error: {
      reason: 'normalization-failure',
      code,
      message,
    },
  };
}

export function floorLookupKey(buildingId: number, floorNumber: number): string {
  return `${buildingId}:${floorNumber}`;
}

export function getEffectiveAccessibleWeight(edge: Pick<NavEdge, 'accessible' | 'accessibleWeight'>): number {
  return edge.accessible ? edge.accessibleWeight : Number.POSITIVE_INFINITY;
}

export function normalizeNavGraph(graph: NavGraph): NavGraphNormalizationResult {
  const buildingById = new Map<number, NavBuilding>();
  const floorById = new Map<number, NormalizedFloorRecord>();
  const floorByBuildingAndNumber = new Map<string, NormalizedFloorRecord>();
  const nodeById = new Map<string, NormalizedNodeRecord>();
  const edgeById = new Map<string, NormalizedEdgeRecord>();
  const outgoingEdgesByNodeId = new Map<string, NormalizedEdgeRecord[]>();

  for (const building of graph.buildings) {
    if (buildingById.has(building.id)) {
      return fail('duplicate-building-id', `Duplicate building id detected: ${building.id}.`);
    }

    buildingById.set(building.id, building);

    for (const floor of building.floors) {
      if (floorById.has(floor.id)) {
        return fail('duplicate-floor-id', `Duplicate floor id detected: ${floor.id}.`);
      }

      const floorKey = floorLookupKey(building.id, floor.floorNumber);
      if (floorByBuildingAndNumber.has(floorKey)) {
        return fail(
          'duplicate-floor-number-per-building',
          `Duplicate floor number ${floor.floorNumber} for building ${building.id}.`,
        );
      }

      const floorRecord: NormalizedFloorRecord = {
        buildingId: building.id,
        buildingName: building.name,
        floor,
      };

      floorById.set(floor.id, floorRecord);
      floorByBuildingAndNumber.set(floorKey, floorRecord);

      for (const node of floor.nodes) {
        if (node.floorId !== floor.id) {
          return fail(
            'node-floor-mismatch',
            `Node ${node.id} reports floorId=${node.floorId}, expected ${floor.id}.`,
          );
        }

        if (nodeById.has(node.id)) {
          return fail('duplicate-node-id', `Duplicate node id detected: ${node.id}.`);
        }

        nodeById.set(node.id, {
          buildingId: building.id,
          buildingName: building.name,
          floorId: floor.id,
          floorNumber: floor.floorNumber,
          node,
        });
      }

      for (const edge of floor.edges) {
        if (edgeById.has(edge.id)) {
          return fail('duplicate-edge-id', `Duplicate edge id detected: ${edge.id}.`);
        }

        const edgeRecord: NormalizedEdgeRecord = {
          buildingId: building.id,
          floorId: floor.id,
          edge,
          effectiveAccessibleWeight: getEffectiveAccessibleWeight(edge),
        };

        edgeById.set(edge.id, edgeRecord);
      }
    }
  }

  for (const edgeRecord of edgeById.values()) {
    const source = nodeById.get(edgeRecord.edge.sourceId);
    const target = nodeById.get(edgeRecord.edge.targetId);

    if (!source || !target) {
      return fail(
        'edge-node-missing',
        `Edge ${edgeRecord.edge.id} references missing node(s): ${edgeRecord.edge.sourceId} -> ${edgeRecord.edge.targetId}.`,
      );
    }

    const currentOutgoing = outgoingEdgesByNodeId.get(source.node.id) ?? [];
    currentOutgoing.push(edgeRecord);
    outgoingEdgesByNodeId.set(source.node.id, currentOutgoing);
  }

  return {
    ok: true,
    data: {
      graph,
      buildingById,
      floorById,
      floorByBuildingAndNumber,
      nodeById,
      edgeById,
      outgoingEdgesByNodeId,
    },
  };
}

export function parseAndNormalizeNavGraph(payload: unknown): NavGraphParseAndNormalizeResult {
  const validated = validateNavGraphPayload(payload);
  if (!validated.ok) {
    return validated;
  }

  return normalizeNavGraph(validated.data);
}

import type { NavGraph } from '../../src/shared/types';
import { z } from 'zod';

const navNodeTypeValues = [
  'room',
  'entrance',
  'elevator',
  'stairs',
  'ramp',
  'restroom',
  'junction',
  'hallway',
  'landmark',
] as const;

const finiteNumber = z.number().finite();
const normalizedCoordinate = finiteNumber.min(0).max(1);
const positiveInt = z.number().int().positive();

const navFloorGpsBoundsSchema = z
  .object({
    minLat: finiteNumber,
    maxLat: finiteNumber,
    minLng: finiteNumber,
    maxLng: finiteNumber,
  })
  .strict()
  .refine((bounds) => bounds.minLat < bounds.maxLat && bounds.minLng < bounds.maxLng, {
    message: 'gpsBounds must satisfy minLat < maxLat and minLng < maxLng',
  });

const navNodeSchema = z
  .object({
    id: z.string().min(1),
    x: normalizedCoordinate,
    y: normalizedCoordinate,
    label: z.string(),
    type: z.enum(navNodeTypeValues),
    searchable: z.boolean(),
    floorId: positiveInt,
    roomNumber: z.string().optional(),
    description: z.string().optional(),
    accessibilityNotes: z.string().optional(),
    connectsToFloorAboveId: positiveInt.optional(),
    connectsToFloorBelowId: positiveInt.optional(),
    connectsToNodeAboveId: z.string().min(1).optional(),
    connectsToNodeBelowId: z.string().min(1).optional(),
    connectsToBuildingId: positiveInt.optional(),
  })
  .strict();

const navEdgeSchema = z
  .object({
    id: z.string().min(1),
    sourceId: z.string().min(1),
    targetId: z.string().min(1),
    standardWeight: finiteNumber.min(0),
    accessibleWeight: finiteNumber.min(0),
    accessible: z.boolean(),
    bidirectional: z.boolean(),
    accessibilityNotes: z.string().optional(),
  })
  .strict();

const navFloorSchema = z
  .object({
    id: positiveInt,
    floorNumber: z.number().int(),
    imagePath: z.string().min(1),
    updatedAt: z.string().min(1),
    gpsBounds: navFloorGpsBoundsSchema.optional(),
    nodes: z.array(navNodeSchema),
    edges: z.array(navEdgeSchema),
  })
  .strict();

const navBuildingSchema = z
  .object({
    id: positiveInt,
    name: z.string().min(1),
    floors: z.array(navFloorSchema),
  })
  .strict();

export const navGraphContractSchema = z
  .object({
    buildings: z.array(navBuildingSchema),
  })
  .strict();

export type NavGraphContract = z.output<typeof navGraphContractSchema>;

export interface NavGraphContractValidationError {
  reason: 'contract-validation-error';
  message: string;
  issues: string[];
}

export type NavGraphValidationResult =
  | { ok: true; data: NavGraph }
  | { ok: false; error: NavGraphContractValidationError };

function formatIssuePath(path: PropertyKey[]): string {
  if (path.length === 0) {
    return 'root';
  }

  return path
    .map((segment) => {
      if (typeof segment === 'number') {
        return `[${segment}]`;
      }

      return typeof segment === 'symbol' ? segment.toString() : segment;
    })
    .join('.');
}

export function validateNavGraphPayload(payload: unknown): NavGraphValidationResult {
  const parsed = navGraphContractSchema.safeParse(payload);

  if (!parsed.success) {
    const issues = parsed.error.issues.map((issue) => `${formatIssuePath(issue.path)}: ${issue.message}`);

    return {
      ok: false,
      error: {
        reason: 'contract-validation-error',
        message: 'Map payload failed contract validation.',
        issues,
      },
    };
  }

  const data: NavGraph = parsed.data;

  return {
    ok: true,
    data,
  };
}

/**
 * PathfindingEngine — dual-mode A* with accessibility filtering.
 *
 * Wraps ngraph.path's A* algorithm with the project's type system.
 * Takes a NavGraph, builds an internal ngraph.graph, and exposes
 * findRoute(fromId, toId, mode) for standard and accessible routing.
 *
 * Used by Phase 6 (route visualization) and Phase 7 (turn-by-turn).
 */

import { buildGraph, calculateWeight } from '@shared/pathfinding/graph-builder'
import type { PathResult, PathSegment, RouteMode } from '@shared/pathfinding/types'
import type { NavEdgeData, NavGraph, NavNodeData } from '@shared/types'
import type { Graph, Link, Node } from 'ngraph.graph'
import type { PathFinder } from 'ngraph.path'
import { aStar } from 'ngraph.path'

/** Not-found result constant — reused for all failure responses. */
const NOT_FOUND: PathResult = Object.freeze({
  found: false,
  nodeIds: [],
  totalDistance: 0,
  segments: [],
})

export class PathfindingEngine {
  private readonly graph: Graph<NavNodeData, NavEdgeData>
  private readonly standardFinder: PathFinder<NavNodeData>
  private readonly accessibleFinder: PathFinder<NavNodeData>

  constructor(navGraph: NavGraph) {
    this.graph = buildGraph(navGraph)

    // Standard finder: uses standardWeight, no edge blocking
    this.standardFinder = aStar<NavNodeData, NavEdgeData>(this.graph, {
      distance: (_from: Node<NavNodeData>, _to: Node<NavNodeData>, link: Link<NavEdgeData>) =>
        link.data.standardWeight,
      heuristic: (a: Node<NavNodeData>, b: Node<NavNodeData>) =>
        a.data.floorId !== b.data.floorId
          ? 0
          : calculateWeight(a.data.x, a.data.y, b.data.x, b.data.y),
    })

    // Accessible finder: uses accessibleWeight, blocks non-accessible edges
    this.accessibleFinder = aStar<NavNodeData, NavEdgeData>(this.graph, {
      distance: (_from: Node<NavNodeData>, _to: Node<NavNodeData>, link: Link<NavEdgeData>) =>
        link.data.accessibleWeight,
      heuristic: (a: Node<NavNodeData>, b: Node<NavNodeData>) =>
        a.data.floorId !== b.data.floorId
          ? 0
          : calculateWeight(a.data.x, a.data.y, b.data.x, b.data.y),
      blocked: (_from: Node<NavNodeData>, _to: Node<NavNodeData>, link: Link<NavEdgeData>) =>
        !link.data.accessible,
    })
  }

  /**
   * Find a route between two nodes.
   *
   * @param fromId - Source node ID
   * @param toId - Destination node ID
   * @param mode - 'standard' or 'accessible'
   * @returns PathResult with found status, ordered nodeIds, segments, and totalDistance
   */
  findRoute(fromId: string, toId: string, mode: RouteMode): PathResult {
    // Same start and destination: trivial path
    if (fromId === toId) {
      return { found: true, nodeIds: [fromId], totalDistance: 0, segments: [] }
    }

    // Validate node existence before calling finder (ngraph throws on missing nodes)
    if (!this.graph.hasNode(fromId) || !this.graph.hasNode(toId)) {
      return { ...NOT_FOUND }
    }

    const finder = mode === 'accessible' ? this.accessibleFinder : this.standardFinder

    const rawPath = finder.find(fromId, toId)

    // ngraph.path returns [targetNode] when all paths are blocked — not a valid path
    if (rawPath.length <= 1) {
      return { ...NOT_FOUND }
    }

    // ngraph.path returns destination-first — reverse to get source-first order
    const path = rawPath.reverse()

    const nodeIds: string[] = []
    const segments: PathSegment[] = []
    let totalDistance = 0

    for (let i = 0; i < path.length; i++) {
      const node = path[i]
      if (!node) continue
      const nodeId = node.id as string
      nodeIds.push(nodeId)

      if (i > 0) {
        const prevNode = path[i - 1]
        if (!prevNode) continue
        const prevId = prevNode.id as string
        const link = this.graph.getLink(prevId, nodeId)

        const distance =
          link != null
            ? mode === 'accessible'
              ? link.data.accessibleWeight
              : link.data.standardWeight
            : 0

        segments.push({ fromId: prevId, toId: nodeId, distance })
        totalDistance += distance
      }
    }

    return { found: true, nodeIds, totalDistance, segments }
  }
}
